package com.yuegang.zhihui.system.api;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.CurrentUserPrincipal;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.system.application.RoleAdministrationService;import com.yuegang.zhihui.system.security.SystemTrustedUserContextResolver;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.List;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/system/admin")public final class RoleAdministrationController{private final RoleAdministrationService service;private final SystemTrustedUserContextResolver users;public RoleAdministrationController(RoleAdministrationService service,SystemTrustedUserContextResolver users){this.service=service;this.users=users;}@GetMapping("/roles")ApiResponse<List<RoleView>>roles(HttpServletRequest request){admin(request);return ok(service.roles(),request);}@PutMapping("/roles/{code}")ApiResponse<RoleView>role(@PathVariable String code,@Valid@RequestBody UpsertRoleRequest body,HttpServletRequest request){admin(request);return ok(service.saveRole(code,body),request);}@GetMapping("/permissions")ApiResponse<List<PermissionView>>permissions(HttpServletRequest request){admin(request);return ok(service.permissions(),request);}@PutMapping("/permissions/{code}")ApiResponse<PermissionView>permission(@PathVariable String code,@Valid@RequestBody UpsertPermissionRequest body,HttpServletRequest request){admin(request);return ok(service.savePermission(code,body),request);}private void admin(HttpServletRequest request){CurrentUserPrincipal user=users.resolve(request);if(!user.roles().contains("ADMIN")&&!user.permissions().contains("system:rbac:write"))throw new BusinessException(ErrorCode.PERMISSION_DENIED);}private static<T>ApiResponse<T>ok(T data,HttpServletRequest request){return ApiResponse.success(data,TraceIdResolver.resolve(request));}}
